"""Sinopses editoriais manuais das 141 medidas comparáveis do lote B."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
NARRATIVAS={}
def grupo(ids,texto):
    for i in ids:NARRATIVAS[i]=texto

grupo([1], 'Flávio impugnou 257 impulsionamentos de vídeo sintético que o associava à ampliação das armas e ao risco para crianças, sob a frase “Com Flávio Bolsonaro, você perde”. O Plenário referendou parcialmente a tutela, após reajuste do voto, restringindo a difusão paga do conteúdo. O fundamento é a vedação do uso de impulsionamento para propaganda negativa, que não se confunde com a licitude da crítica difundida organicamente.')
grupo([28], 'Flávio questionou impulsionamentos pagos realizados pela campanha de Lula no Facebook e Instagram, apontados como propaganda negativa contra sua candidatura. A certidão de julgamento comprova o referendo unânime da tutela parcialmente deferida, após reajuste do voto da relatora. A providência incide sobre o material individualizado e sua amplificação paga, sem se confundir com proibição geral de crítica política.')
grupo([4,8,10,25,40,46,47,73], 'Flávio pediu resposta à propaganda que associava sua candidatura e a proposta de ajuste fiscal a cortes de recursos para programas sociais durante o governo de Jair Bolsonaro. O Plenário rejeitou o pedido: a associação entre projetos políticos e o prognóstico desfavorável foram tratados como crítica eleitoral, sem afirmação categoricamente falsa apta a justificar resposta. A rejeição das preliminares não significou acolhimento da pretensão material.')
grupo([12,26,49], 'Flávio pediu resposta à propaganda que relacionava a flexibilização do acesso a armas e munições ao aumento da violência e ao armamento de organizações criminosas. O Plenário julgou o pedido improcedente, distinguindo a crítica ao legado de uma política pública da imputação pessoal de participação criminosa. A controvérsia sobre indicadores de segurança, no contexto examinado, não demonstrou falsidade manifesta.')
grupo([13,14,71], 'Flávio requereu a suspensão da propaganda que aproximava o “tesouraço” de cortes na Farmácia Popular, no combate ao câncer e no financiamento habitacional. A negativa cautelar foi referendada por unanimidade: o juízo entendeu que a comparação entre o ajuste fiscal anunciado e medidas do governo anterior permanecia no debate político. O processo seguiu para contraditório, sem julgamento definitivo da representação.')
grupo([15,17,19,27,63,69,99,114,145], 'A coligação de Lula impugnou a identificação da chapa de Flávio na propaganda eleitoral, sustentando ausência ou ilegibilidade do nome de Alfredo Gaspar. A tutela impediu nova veiculação da peça enquanto não adequada à identificação do vice, com clareza e proporção legal em relação ao titular. O Plenário manteve a providência, com fundamento no art. 36, § 4º, da Lei das Eleições e no art. 12 da Resolução TSE nº 23.610/2019.')
grupo([16], 'Flávio pretendia suspender a propaganda de rádio que ligava a política de acesso a armas ao aumento da violência e ao abastecimento da criminalidade. O Plenário referendou a negativa da liminar: a mensagem foi considerada crítica político-eleitoral, sem falsidade manifesta que autorizasse restrição imediata. O mérito permaneceu aberto.')
grupo([18,29], 'Flávio apontou, no programa televisivo da campanha de Lula, falta de identificação de Geraldo Alckmin, desinformação sobre programas sociais e utilização irregular de inteligência artificial. A tutela acolheu a exigência de identificação do vice nos trechos de identificação eleitoral da chapa, mas não suspendeu os demais conteúdos pelas razões inicialmente alegadas. O Plenário referendou o atendimento parcial, sem antecipar o exame definitivo das outras matérias.')
grupo([20,21,33], 'A coligação de Lula pediu resposta à frase “o Brasil tá sem presidente”, pronunciada no quadro “Plantão Fake News” do programa de Flávio. O Plenário julgou a pretensão improcedente: a expressão foi examinada como avaliação crítica da condução do governo, e não como afirmação literal de vacância da Presidência. O resultado é de mérito sobre o pedido de resposta.')
grupo([22,62,68,90], 'A coligação de Lula contestou a peça “Lula prometeu picanha, mas entregou a fila do osso”, que utilizava vídeos verdadeiros de doações privadas de alimentos. A tutela restringiu a circulação da montagem individualizada por apresentar essas iniciativas independentes como resultados diretamente produzidos pela gestão presidencial, associação causal não demonstrada. A providência é cautelar e não concede, por si, o direito de resposta definitivo.')
grupo([30,61], 'A coligação de Lula questionou vídeo que afirmava que os problemas haviam piorado após governos do PT e, nesse momento, mostrava homens encapuzados com fuzis. O juízo não identificou probabilidade suficiente de atribuição pessoal e ilícita de vínculo com a criminalidade e negou a restrição cautelar. O resultado mais recente mantém essa negativa; a discussão sobre a resposta ou o mérito da propaganda permanece distinta.')
grupo([31], 'A coligação de Lula impugnou montagem de trechos de declarações públicas que, segundo a inicial, modificava o sentido original das falas. A ordem de retirada do vídeo foi mantida no referendo por maioria, por grave descontextualização e extrapolação da crítica política. André Mendonça, Dias Toffoli e Nunes Marques ficaram vencidos em parte; o pronunciamento conserva natureza cautelar.')
grupo([32,64,70,97], 'A coligação de Lula impugnou a inserção “Vem com Flávio”, apontando falta de identificação do vice e excesso de participação de apoiadores. A ordem suspendeu a versão original até a inclusão legível do nome de Alfredo Gaspar na proporção legal e a limitação dos apoiadores a 25% do tempo. A providência admite peça corrigida e se apoia nas regras de identificação da chapa e participação de terceiros na propaganda gratuita.')
grupo([34,77,111], 'A coligação de Lula pediu resposta e suspensão do quadro “Plantão Fake News”, que afirmava que “o Brasil tá sem presidente”. O relator considerou a frase uma crítica política de sentido figurado, insuficiente para demonstrar falsidade manifesta ou grave ofensa pessoal, e indeferiu a tutela. A resposta definitiva depende do exame posterior do mérito.')
grupo([35,36,78,79,81], 'A coligação de Lula contestou programa de Flávio que dizia que “o Brasil está sem presidente” e apontou irregularidade na identificação do vice; em parte dessas peças também foi discutida a posição de Lula sobre saídas temporárias. O pronunciamento negou a suspensão cautelar por ausência de ilicitude manifesta na comunicação e dos requisitos para intervenção imediata. A negativa não equivale à improcedência definitiva da representação ou do pedido de resposta.')
grupo([37,38,74], 'A coligação de Lula questionou inserção que alternava falas reais do candidato com a interjeição “Mentira!” e terminava advertindo que ele mentiria novamente. O conteúdo foi tratado como juízo político crítico, sem demonstração de que a montagem criasse um fato objetivamente falso suficiente para a intervenção excepcional. A providência comunicacional não foi acolhida; o estágio é o especificado na peça de referência.')
grupo([39], 'Flávio impugnou publicações que associavam sua proposta de ajuste fiscal a cortes em políticas sociais, obtendo inicialmente retirada parcial. No referendo, o relator reajustou o voto e o Plenário, por unanimidade, revogou a tutela, tornou sem efeito as ordens de remoção e permitiu o restabelecimento das postagens. Prevaleceu a proteção da crítica política, sem encerramento do mérito.')
grupo([42], 'Flávio impugnou postagem do PT que apresentava como anúncio confirmado da campanha um corte de R$ 250 bilhões em saúde, educação e Previdência, a partir de notícia sobre hipótese em avaliação. A retirada da publicação individualizada foi concedida parcialmente e mantida por maioria, por possível transformação de informação condicional em anúncio categórico. Floriano de Azevedo Marques e Estela Aranha ficaram vencidos; não foi acolhida uma proibição genérica de conteúdos futuros.')
grupo([45], 'A coligação de Lula questionou publicações sobre a Marcha pela Democracia, na Avenida Paulista, que associavam seus participantes de modo generalizado a ilícitos e a comportamentos depreciativos. A tutela foi parcialmente acolhida e mantida, nos limites reajustados da medida sobre os conteúdos individualizados. A decisão não transforma toda crítica à manifestação ou a seus participantes em propaganda ilícita.')
grupo([51], 'Flávio contestou publicação colaborativa que o mostrava com uma tesoura diante da Farmácia Popular e aproximava notícia de 2022 de hipótese de ajuste fiscal noticiada em 2026. O juízo observou que as fontes e os anos estavam identificados e que a manchete dizia “avalia, se eleito”, tratando a composição como crítica e prognóstico eleitoral. O Plenário referendou a negativa da liminar.')
grupo([53], 'A coligação de Lula pediu a retirada de vídeo em que Flávio apresentava propostas e dizia querer que o pobre ficasse rico, em contraposição à suposta intenção de Lula de mantê-lo miserável. O juízo não reconheceu, no exame sumário, os pressupostos para restringir essa comparação retórica entre projetos políticos. O Plenário manteve a negativa cautelar por unanimidade.')
grupo([57], 'Flávio impugnou postagem colaborativa dos perfis Brasil com Lula e Anielle Franco com a frase “Votar em Flávio Bolsonaro é votar em quatro anos da milícia no poder”. A tutela restringiu parcialmente a publicação individualizada, distinguindo críticas a políticas públicas da associação pessoal sem substrato mínimo a uma organização criminosa. O Plenário manteve a medida, sem acolher uma proibição geral de crítica política.')
grupo([58], 'A coligação de Lula impugnou publicação que atribuía ao candidato intenção de fechar igrejas. A relatora identificou falta de suporte factual para essa afirmação e determinou a retirada do conteúdo, mantida por unanimidade no referendo. A ordem é provisória e se dirige à publicação examinada.')
grupo([59,60], 'A coligação de Lula questionou anúncios pagos que o responsabilizavam pelo abandono do País e apresentavam Flávio como alternativa, com conteúdo predominantemente depreciativo do adversário. A tutela restringiu o impulsionamento do material individualizado e foi referendada. A razão é a vedação de amplificação paga de propaganda negativa; o atendimento deve conservar o alcance integral ou parcial registrado em cada processo.')
grupo([65], 'A coligação de Lula impugnou postagens que afirmavam gasto de R$ 7 bilhões em viagens internacionais do Presidente e da primeira-dama. No referendo, prevaleceu a divergência de Sebastião Reis Júnior, que concedeu a remoção, em substituição à negativa inicial. Ficaram vencidos o relator, André Mendonça e Dias Toffoli; o resultado favorável continua cautelar.')
grupo([67], 'A coligação de Lula contestou vídeo divulgado no Dia das Crianças, com crianças em encenação que associava Lula e seu filho a furtos, insegurança e problemas econômicos. A tutela parcialmente concessiva foi mantida por maioria, vencido em parte Floriano de Azevedo Marques. A intervenção recai sobre os elementos individualizados do vídeo, sem interdição geral de críticas políticas ou conclusão de mérito.')
grupo([75], 'A coligação de Lula impugnou imagem sintética de mulher negra limpando pichações na estação Trianon-Masp após a Marcha pela Democracia, apresentada como registro verdadeiro. O relator determinou a retirada de publicações específicas, inclusive uma do PL, e proibiu difundir a mesma imagem como fato real. Negou por ora a tutela contra Flávio quanto ao canal de WhatsApp e outras extensões não comprovadas; por isso o atendimento é parcial.')
grupo([80], 'Flávio contestou peça televisiva que o associava às milícias, por meio de depoimentos, fala de 2007 e editorial jornalístico. A tutela concessiva foi mantida por unanimidade, com fundamentação diversa de Floriano de Azevedo Marques, protegendo o candidato contra a associação comunicacional examinada. A certidão comprova o referendo; a restrição não constitui julgamento definitivo da representação.')
grupo([84], 'Flávio impugnou anúncios pagos do vídeo “Lembre-se do Miguel” ou “Tal pai, tal filho”, que o associava à indiferença diante da fome e da vulnerabilidade social. O Plenário referendou parcialmente a tutela contra o impulsionamento negativo, preservando a distinção entre promoção remunerada e circulação orgânica. O mérito das sanções permaneceu separado da cautelar.')
grupo([85], 'A coligação de Lula impugnou a transformação de fala de Flávio em peça oficial segundo a qual integrantes do PCC votariam em Lula porque ele os representaria e protegeria. A tutela restringiu parcialmente as publicações individualizadas por associação pessoal à organização criminosa sem substrato factual mínimo. O Plenário referendou a providência por unanimidade, sem proibir críticas distintas à segurança pública.')
grupo([87], 'Flávio questionou postagem colaborativa de Marcelo Freixo e da campanha de Lula que ligava seu voto a Vorcaro, à milícia e a Trump. A tutela alcançou a publicação individualizada e sua reprodução sob controle dos representados, pela associação pessoal à criminalidade sem suporte suficiente, mas recusou ordem genérica sobre conteúdos futuros. O resultado é parcialmente favorável na etapa cautelar.')
grupo([89], 'Flávio obteve inicialmente a retirada parcial de postagem que o apresentava como contrário ao fim da escala 6x1. No referendo, venceu a divergência de Sebastião Reis Júnior e o pedido de remoção foi negado, por maioria. O resultado mais recente substitui a tutela inicial, sem antecipar o mérito definitivo.')
grupo([91], 'A coligação de Lula obteve inicialmente tutela contra vídeo que lhe atribuía responsabilidade pelo endividamento, inflação e perda de renda das famílias. No referendo, prevaleceu o voto de Dias Toffoli e a liminar não foi mantida, vencidas a relatora e a posição de Floriano de Azevedo Marques. O resultado comparável passou a ser negativo, ainda na etapa provisória.')
grupo([92], 'A coligação de Lula obteve liminar contra propaganda que recortava falas do candidato de modo a associá-lo à criminalidade. A certidão posterior registra que, por maioria, o Plenário não referendou a concessão, prevalecendo o voto de André Mendonça e ficando vencida apenas a relatora. A extinção posterior da resposta pelo fim do pleito não altera essa reversão cautelar.')
grupo([93,95], 'A coligação de Lula contestou a peça “Com o Lula, não dá mais”, que utilizava números de endividamento, feminicídios e denúncias de trabalho escravo para criticar a gestão. A relatora não reconheceu falsidade objetiva ou distorção grave inequívoca nas informações jornalísticas, negando a restrição imediata. O Plenário manteve a negativa por unanimidade.')
grupo([94,96], 'A coligação de Lula impugnou bloco televisivo por identificação inadequada do vice e por utilização depreciativa de informações jornalísticas. A tutela acolheu a necessidade de regularizar a identificação da chapa, mas afastou, em exame sumário, a alegação de desinformação grave sobre a gestão. O Plenário referendou o atendimento parcial.')
grupo([102], 'Flávio pediu resposta a inserções sobre seu posicionamento quanto à escala 6x1, jornada e remuneração do trabalho. O Plenário considerou que o confronto entre posições pretéritas, mudança de orientação e prognósticos eleitorais integrava a crítica política, sem falsidade manifesta ou grave ofensa pessoal. O pedido de resposta foi julgado improcedente.')
grupo([103], 'Flávio questionou programa de televisão de 14/10 que o associava a uma maçã em putrefação e destacava Lula sem a identificação legal do vice. A tutela proibiu o trecho da maçã e condicionou a reexibição dos demais segmentos à identificação legível de Geraldo Alckmin na proporção legal. A decisão admite material corrigido e não encerra o mérito.')
grupo([105], 'A coligação de Lula impugnou vídeo no canal Tropa do Flávio, montado como mural de investigação, com dados sobre dívidas, fome e empresas, além de referências a corrupção. A ordem determinou a retirada da publicação individualizada, mas recusou proibição genérica de outras mensagens idênticas ou equivalentes sem indicação específica. A decisão conserva natureza cautelar.')
grupo([108], 'Flávio impugnou a inserção “Flávio Bolsonaro é duas caras. Ele sempre foi contra o fim da escala seis por um”. O relator suspendeu a peça e sua transposição para outros formatos do horário gratuito, determinando comunicação às emissoras, por possível descontextualização do posicionamento atribuído ao candidato. A medida é provisória, até o exame do mérito.')
grupo([109,113], 'A coligação de Lula pediu a suspensão da propaganda que atribuía a militantes do PT atos de vandalismo após a Marcha pela Democracia e encerrava com “O Brasil está sem presidente”. O juízo não identificou falsidade ou descontextualização grave suficiente para restringir a crítica no exame inicial. O Plenário manteve a negativa; não houve conclusão definitiva sobre toda a controvérsia.')
grupo([110,112,126,127], 'A coligação de Lula contestou a peça sobre “recordes de incompetência”, que reproduzia notícias de feminicídios, denúncias de trabalho escravo e recuperações judiciais. O pronunciamento não encontrou distorção grave e inequívoca na crítica construída a partir desses indicadores e negou a suspensão. O mérito e, quando cabível, a resposta definitiva permaneceram separados da cautelar.')
grupo([115], 'A coligação de Lula impugnou montagem que alternava declarações públicas do candidato e imagens de violência explícita, alterando o sentido contextual das falas. A ordem de retirada foi referendada por maioria, vencidos André Mendonça, Dias Toffoli e Nunes Marques. A exclusão processual da Meta não afasta a obrigação da provedora de cumprir a ordem sobre os conteúdos indicados.')
grupo([116,119], 'Flávio contestou propaganda que dizia que ele sempre fora contrário ao fim da escala 6x1 e ameaçaria reverter essa conquista. O juízo considerou que o debate sobre seu posicionamento e as consequências políticas de eventual governo não justificava, naquele momento, a intervenção excepcional. A tutela foi negada sem exame exauriente do mérito.')
grupo([117], 'Flávio impugnou o conjunto de anúncios pagos “Com Flávio Bolsonaro, você perde”, veiculado a partir da página Lula. A tutela suspendeu os impulsionamentos identificados, inclusive os agrupamentos descritos na decisão, e proibiu novas contratações do mesmo conteúdo negativo. Foram preservadas as informações de gastos e alcance; a ordem prospectiva genérica foi recusada.')
grupo([118], 'Flávio questionou o anúncio Meta ID 852704987899762 e os demais anúncios que utilizassem o mesmo vídeo e legenda. A tutela suspendeu o impulsionamento e vedou nova promoção paga desse conteúdo, preservando expressamente sua publicação orgânica. O fundamento é a vedação de impulsionamento negativo, e não uma declaração de ilicitude de toda crítica contida no vídeo.')
grupo([120,143,200], 'A coligação de Lula contestou a inserção “A lobista do careca do INSS, aquele dos aposentados”, que aproximava imagens de Lula, Fábio Luís e Roberta Luchsinger dos descontos indevidos em benefícios e de gastos de luxo. A tutela impediu nova veiculação da peça, pela associação descontextualizada e sem suporte suficiente que lhe era atribuída. A ordem é comunicacional e provisória, sem julgamento sobre a responsabilidade criminal das pessoas mencionadas.')
grupo([123], 'A coligação de Lula questionou programa televisivo de 15/10 por ausência de identificação adequada do vice e por narrativa sobre a Marcha pela Democracia. A tutela acolheu a regularização da identificação da chapa, mas não restringiu naquele exame o conteúdo sobre a manifestação. O atendimento é parcial e permite a reexibição de peça corrigida.')
grupo([124], 'A coligação de Lula impugnou a inserção “A campanha do Lula esconde quem é o verdadeiro Lula”, que reunia falas sobre mulheres proferidas em ocasiões distintas e terminava com “O Brasil está sem presidente”. O relator determinou a suspensão da montagem individualizada, por possível alteração descontextualizada do sentido das declarações. A restrição se limita à composição examinada e não antecipa o mérito.')
grupo([130,142,155,159,170,172,185,190], 'A coligação de Lula questionou a peça “Com o Lula a violência no Brasil só aumentou e você vive com medo”, com afirmações sobre endividamento, alimentos, renda e insegurança. O juízo considerou que a linguagem negativa e os prognósticos desfavoráveis, sem demonstração de falsidade manifesta ou grave distorção, permaneciam no campo da crítica política. A medida de suspensão foi negada na etapa cautelar.')
grupo([132], 'Flávio impugnou inserção que o retratava como maçã apodrecida e dizia que defendera o assassino de uma criança de cinco anos. A tutela restringiu a peça nos limites fixados e vedou repetir a segunda imputação sem indicar que a atuação ocorrera no exercício da advocacia. Admitiu versão readequada, mantendo a decisão como exame provisório da comunicação.')
grupo([133], 'Flávio contestou bloco de rádio que lhe atribuía propostas sobre aposentadoria, jornada, armas e corte de programas sociais. A relatora não identificou, no exame inicial, os requisitos para suspender a propaganda, ressaltando a proteção reforçada à manifestação no debate eleitoral. O indeferimento é liminar e não constitui julgamento definitivo das alegações.')
grupo([136,137], 'A coligação de Lula questionou recorte de entrevista de 2024 sobre visitas familiares de presos, associado a imagens de saída de unidade prisional e criminalidade. O juízo não reconheceu probabilidade bastante de descontextualização ilícita para suspender imediatamente a propaganda. O pedido material de resposta ou o mérito da representação permaneceu aberto.')
grupo([138,161,173,188,204,213,215,217,218], 'A coligação de Lula impugnou a associação de sua fala sobre visita familiar de presos a manchetes e imagens de crimes, sob a afirmação de apoio às “saidinhas”. O relator determinou a suspensão da peça ou do trecho individualizado e de versões que preservassem a mesma associação descontextualizada. A providência é cautelar; não impede o debate distinto sobre a política de execução penal.')
grupo([146], 'Flávio impugnou a peça “Filme 49”, que o apresentava como articulador de golpe para acabar com o descanso da escala 6x1 e lhe atribuía fala fictícia em primeira pessoa. A tutela foi parcialmente acolhida e mantida pelo Plenário por unanimidade. A decisão limita a restrição à composição examinada, sem impedir críticas lícitas ao posicionamento trabalhista do candidato.')
grupo([148], 'Flávio questionou o “Filme 45”, que o ligava a pessoa investigada no caso Marielle e o apresentava como contrário ao fim da escala 6x1. A tutela proibiu a veiculação da inserção e de versões que repetissem as associações delimitadas, até ulterior deliberação. O resultado é parcialmente favorável e provisório, sem decisão sobre responsabilidade penal ou sobre toda manifestação política relativa aos temas.')
grupo([149], 'A coligação de Lula questionou a recomendação de conteúdos dos perfis de Nikolas Ferreira e Pablo Marçal, em AIJE também proposta contra a chapa de Flávio. Em 23/10, a tutela recusou excluir integralmente os perfis das recomendações, mas impôs a aplicação da política declarada pela Meta aos conteúdos eleitorais individualizados e uma ordem inibitória parcial até o fim da votação. As providências não se confundem com suspensão geral dos perfis; o mérito da AIJE permaneceu aberto.')
grupo([150], 'Flávio contestou inserção que associava seu corte de R$ 250 bilhões a prejuízos para Bolsa Família, Pé-de-Meia, Farmácia Popular, salário mínimo e aposentadorias. O Plenário manteve a negativa da suspensão, preservando a crítica política e o confronto de prognósticos sobre o ajuste fiscal. O resultado é cautelar, sem decisão final sobre a representação.')
grupo([153], 'A coligação de Lula impugnou “Pegadinha do Lulão”, vídeo sintético que simulava o candidato em podcast, atribuindo-lhe promessa sobre Mounjaro e respostas depreciativas sobre promessas eleitorais. A tutela retirou as publicações específicas e determinou a atuação da plataforma, preservando registros. Foi recusada uma ordem genérica sobre outras mensagens futuras; o resultado é parcialmente favorável e provisório.')
grupo([154], 'A coligação de Lula questionou vídeo que alternava recortes de fala do candidato sobre assalto e imagens de um crime real, sob a apresentação “É nisso que Lula acredita”. A tutela ordenou a retirada das URLs individualizadas e proibiu nova difusão da mesma montagem ou conteúdo substancialmente equivalente. O fundamento é a possível alteração grave de sentido produzida pela associação audiovisual, ainda em cognição sumária.')
grupo([176], 'Flávio impugnou a associação da frase “Sou filho do Presidente. Quer me dar?” a encenações de abordagem de mulheres em uma padaria. Após restringir a peça no horário gratuito e na internet, o relator estendeu a tutela à republicação apresentada como “vídeo proibido pelo TSE” e fixou multa de R$ 50 mil nas hipóteses de descumprimento delimitadas. A ordem alcança a peça específica, não outras críticas ao candidato.')
grupo([178], 'Flávio impugnou impulsionamentos da peça “O Bolsa Família está ameaçado”, encerrada com “O tesouraço do Flávio é contra você”. A tutela suspendeu a promoção paga dos anúncios identificados e restringiu novas contratações do mesmo conteúdo negativo. A ordem é parcial e provisória e não equivale à retirada geral de críticas orgânicas sobre programas sociais.')
grupo([179], 'Flávio contestou dez impulsionamentos de vídeo intitulado “Flávio defendeu assassino de criança”, que reunia trecho de debate e depoimento da mãe da vítima. A tutela parcialmente concessiva contra a promoção remunerada foi referendada por unanimidade. A vedação ao impulsionamento negativo e a preservação dos dados das campanhas pagas não resolvem definitivamente o mérito de toda a narrativa.')
grupo([180], 'Flávio impugnou anúncios pagos com o desafio “Abra seu sigilo bancário, Flávio Bolsonaro”, derivados de fala de Lula no debate e acompanhados de insinuações de corrupção. O relator restringiu o impulsionamento dos criativos identificados e determinou preservação de gastos, segmentação e alcance. A providência é parcial e cautelar, fundada no regime de promoção remunerada negativa.')
grupo([181], 'A coligação de Lula impugnou o anúncio Meta ID 1833720587771128, atribuído à campanha de Flávio e apontado como impulsionamento negativo. A tutela vedou a amplificação remunerada do conteúdo identificado, preservando expressamente a circulação orgânica e recusando ordem genérica sobre futuras propagandas. O mérito ficou pendente.')
grupo([183], 'A coligação de Lula impugnou o vídeo “O Brasil precisa de pacificação, não de revanchismo”, que utilizava falas presidenciais para sugerir punição a Estados governados por adversários. A tutela foi parcialmente acolhida sobre as publicações individualizadas, por possível alteração descontextualizada do sentido das manifestações. Foram recusadas a retirada de URLs não identificadas e a proibição geral de novas falas sobre os temas.')
grupo([187,189], 'A coligação de Lula contestou o recorte de áudio atribuído a Vorcaro e a interlocutor não identificado, publicado com a legenda “Do Lula foi por fora, Vorcaro?”. O juízo não reconheceu probabilidade suficiente de falsidade manifesta ou imputação pessoal inequivocamente ilícita para restringir a publicação na etapa inicial. A tutela foi negada, sem julgamento definitivo do pedido de resposta ou da representação.')
grupo([192], 'Flávio pretendia suspender comunicações governamentais pelos canais Gov.br/WhatsApp e retirar a marca “União e Reconstrução”. A decisão de 24/10 manteve a negativa da suspensão em reconsideração, por insuficiência dos elementos para justificar a restrição imediata. Os pedidos de preservação e a apuração do alegado uso eleitoral dos canais seguiram separados do resultado cautelar.')
grupo([195], 'A coligação de Lula pretendia a indisponibilização integral do sítio flaviometro.com, apontando estrutura de distribuição de propaganda negativa. O relator negou a retirada integral, mas determinou preservação e obtenção de dados de hospedagem, registro e administração. Essas diligências são probatórias e não contam como atendimento do pedido de suspensão do sítio.')
grupo([197], 'Flávio questionou a inserção “Áudio 50”, que usava o desafio de abrir sigilos para associá-lo a valores de Vorcaro, descontos do INSS e à compra de uma mansão. A tutela restringiu a veiculação nos limites descritos e recusou a ordem genérica de abstenção e parte das afirmações impugnadas. O resultado é parcialmente favorável e provisório, sem conclusão sobre ilícitos criminais mencionados na propaganda.')
grupo([198], 'A coligação de Lula impetrou mandado de segurança contra medidas administrativas que restringiam o canal “Exército do Lula”, com Flávio como litisconsorte passivo. Em 23/10, a liminar suspendeu medidas em nível de canal nos procedimentos apontados e preservou seu funcionamento até pronunciamento jurisdicional competente. O deferimento é parcial e não declara lícito todo o conteúdo difundido no canal.')
grupo([202], 'A coligação de Lula questionou suposto favorecimento algorítmico de perfis ligados a Flávio e a retirada do vídeo “Flavinho de Papai”. Em 24/10, a tutela vedou amplificação excepcional dos perfis individualizados e determinou revisão humana do vídeo, com restabelecimento condicionado à ausência de causa legítima para remoção. A restauração judicial imediata e outros pedidos foram reservados; o atendimento é parcial.')
grupo([206], 'A coligação de Lula impugnou postagens com imagens de pessoas detidas em Piracicaba usando camisetas de Lula, utilizadas para aproximar o candidato e o PT da criminalidade. A relatora ordenou a retirada dos conteúdos individualizados e a abstenção de republicar o mesmo núcleo audiovisual. A decisão cautelar não impõe proibição genérica de noticiar a ocorrência policial.')
grupo([225], 'Flávio alegou uso da estrutura da Rádio Nacional em benefício de Lula no programa “Alô Alô Brasil”, com destaque para a edição de 20/10 e trechos anteriores. A Corregedoria recebeu a AIJE, mas negou as medidas urgentes de restrição do programa nos termos postulados, reservando outros requerimentos. O recebimento da ação não reconhece o abuso e a negativa cautelar não antecipa o mérito.')
grupo([226], 'Flávio apontou estrutura coordenada de comunicação digital da campanha de Lula e pediu suspensão de anúncios, retirada de conteúdos e cessação de ordens de mobilização. A Corregedoria recebeu a AIJE, mas negou essas medidas por insuficiência de prova que lhes desse suporte no exame inicial. A retificação da Meta como terceira interessada e a continuação da instrução não constituem atendimento comunicacional.')
grupo([227], 'A coligação de Lula pediu a suspensão do canal Tropa do Flávio e medidas contra a difusão de conteúdos ilícitos, acrescentando áudio que alegava votos lançados por mesários em nome de ausentes. A Corregedoria negou fechar todo o canal, mas proibiu republicações delimitadas e determinou a retirada do áudio específico, com multa coercitiva. O atendimento é parcial e cautelar, sem julgamento do mérito da AIJE.')
grupo([228], 'Flávio questionou o manifesto e o formulário foraflavio.com.br, sua base de dados e anúncios de terceiros supostamente favoráveis à chapa de Lula. A tutela negou a suspensão e a abstenção por falta de demonstração de uso efetivo dos dados em favor dos candidatos e não conheceu do pedido sobre anúncios já levados a outra representação. A instrução e os pedidos de preservação permaneceram separados da negativa comunicacional.')

def main():
    path=ROOT/'curadoria_novos_b.json';dados=json.loads(path.read_text(encoding='utf-8'))
    incluidos={v['revisao_outubro']['indice_lote_b'] for v in dados.values() if v['incluir']}
    assert incluidos <= NARRATIVAS.keys(), sorted(incluidos-NARRATIVAS.keys())
    for v in dados.values():
        i=v['revisao_outubro']['indice_lote_b']
        if not v['incluir']:continue
        v['sinopse']=NARRATIVAS[i]
        d=v.get('data_julgamento_no_corpo')
        v['sinopse']+=f" A peça de referência foi registrada em {v['data_ato_referencia'][8:10]}/{v['data_ato_referencia'][5:7]}."
        if d and d!=v['data_ato_referencia']:v['sinopse']+=f" O julgamento é datado no corpo em {d[8:10]}/{d[5:7]}."
        if 'resposta extinta' in v['status']:v['sinopse']+=' Após o segundo turno, a resposta foi extinta sem novo exame dessa medida comunicacional.'
        if i==65:v['status']='tutela deferida diretamente no referendo; negativa inicial modificada'
        v['relato']['texto']=v['sinopse']
    path.write_text(json.dumps(dados,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Sinopses específicas:',len(incluidos))

if __name__=='__main__':main()
